import Database from 'better-sqlite3';
import { join } from 'path';

// Resolve database path
const dbPath = join(process.cwd(), 'blog.db');

const db = new Database(dbPath);

// Initialize table
db.exec(`
  CREATE TABLE IF NOT EXISTS posts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    slug TEXT UNIQUE NOT NULL,
    body TEXT NOT NULL,
    tags TEXT NOT NULL, -- JSON array of strings
    published INTEGER NOT NULL -- 1 for true, 0 for false
  )
`);

export interface Post {
  id: number;
  title: string;
  slug: string;
  body: string;
  tags: string[]; // parsed from JSON
  published: boolean;
}

export function getPosts(): Post[] {
  const rows = db.prepare('SELECT * FROM posts ORDER BY id DESC').all() as any[];
  return rows.map(row => ({
    id: row.id,
    title: row.title,
    slug: row.slug,
    body: row.body,
    tags: JSON.parse(row.tags),
    published: row.published === 1,
  }));
}

export function getPublishedPosts(): Post[] {
  const rows = db.prepare('SELECT * FROM posts WHERE published = 1 ORDER BY id DESC').all() as any[];
  return rows.map(row => ({
    id: row.id,
    title: row.title,
    slug: row.slug,
    body: row.body,
    tags: JSON.parse(row.tags),
    published: true,
  }));
}

export function getPostBySlug(slug: string): Post | null {
  const row = db.prepare('SELECT * FROM posts WHERE slug = ?').get(slug) as any;
  if (!row) return null;
  return {
    id: row.id,
    title: row.title,
    slug: row.slug,
    body: row.body,
    tags: JSON.parse(row.tags),
    published: row.published === 1,
  };
}

export function deletePost(slug: string): void {
  db.prepare('DELETE FROM posts WHERE slug = ?').run(slug);
}

export function isSlugUnique(slug: string, excludeId?: number): boolean {
  if (excludeId !== undefined) {
    const row = db.prepare('SELECT COUNT(*) as count FROM posts WHERE slug = ? AND id != ?').get(slug, excludeId) as any;
    return row.count === 0;
  } else {
    const row = db.prepare('SELECT COUNT(*) as count FROM posts WHERE slug = ?').get(slug) as any;
    return row.count === 0;
  }
}

export function createPost(post: Omit<Post, 'id' | 'slug'>): Post {
  const tagsJson = JSON.stringify(post.tags);
  const publishedVal = post.published ? 1 : 0;

  // Generate unique slug
  const slug = generateSlug(post.title, (s) => isSlugUnique(s));

  const result = db.prepare(
    'INSERT INTO posts (title, slug, body, tags, published) VALUES (?, ?, ?, ?, ?)'
  ).run(post.title, slug, post.body, tagsJson, publishedVal);

  return {
    id: result.lastInsertRowid as number,
    title: post.title,
    slug,
    body: post.body,
    tags: post.tags,
    published: post.published,
  };
}

export function updatePost(id: number, post: Omit<Post, 'id' | 'slug'> & { slug?: string }): void {
  const tagsJson = JSON.stringify(post.tags);
  const publishedVal = post.published ? 1 : 0;

  // If a slug is already provided and we want to keep it, or we need to generate a new slug because the title changed.
  // Let's check:
  const currentPost = db.prepare('SELECT * FROM posts WHERE id = ?').get(id) as any;
  if (!currentPost) {
    throw new Error(`Post with id ${id} not found`);
  }

  let finalSlug = currentPost.slug;
  if (post.title !== currentPost.title) {
    finalSlug = generateSlug(post.title, (s) => isSlugUnique(s, id));
  }

  db.prepare(
    'UPDATE posts SET title = ?, slug = ?, body = ?, tags = ?, published = ? WHERE id = ?'
  ).run(post.title, finalSlug, post.body, tagsJson, publishedVal, id);
}

// Helper for slug generation
export function generateSlug(title: string, isUniqueCheck: (slug: string) => boolean): string {
  let baseSlug = title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');

  if (!baseSlug) {
    baseSlug = 'post';
  }

  if (isUniqueCheck(baseSlug)) {
    return baseSlug;
  }

  let n = 2;
  while (true) {
    const candidate = `${baseSlug}-${n}`;
    if (isUniqueCheck(candidate)) {
      return candidate;
    }
    n++;
  }
}

import { createServerFn } from '@tanstack/react-start'
import { getPosts, getPublishedPosts, getPostBySlug, createPost, updatePost, deletePost, Post } from './db'

export function parseTags(tagsString: string): string[] {
  return tagsString
    .split(',')
    .map(t => t.trim())
    .filter(t => t.length > 0);
}

export const getPostsFn = createServerFn({ method: 'GET' })
  .validator((d: { admin?: boolean; tag?: string } | undefined) => d)
  .handler(async ({ data }) => {
    const admin = data?.admin ?? false;
    const tag = data?.tag;

    let posts = admin ? getPosts() : getPublishedPosts();

    if (tag) {
      posts = posts.filter(post => post.tags.includes(tag));
    }

    return posts;
  })

export const getPostBySlugFn = createServerFn({ method: 'GET' })
  .validator((slug: string) => slug)
  .handler(async ({ data: slug }) => {
    return getPostBySlug(slug);
  })

export const createPostFn = createServerFn({ method: 'POST' })
  .validator((data: { title: string; body: string; tags: string; published: boolean }) => data)
  .handler(async ({ data }) => {
    const parsedTags = parseTags(data.tags);
    return createPost({
      title: data.title,
      body: data.body,
      tags: parsedTags,
      published: data.published,
    });
  })

export const updatePostFn = createServerFn({ method: 'POST' })
  .validator((data: { id: number; title: string; body: string; tags: string; published: boolean }) => data)
  .handler(async ({ data }) => {
    const parsedTags = parseTags(data.tags);
    updatePost(data.id, {
      title: data.title,
      body: data.body,
      tags: parsedTags,
      published: data.published,
    });
    return { success: true };
  })

export const deletePostFn = createServerFn({ method: 'POST' })
  .validator((slug: string) => slug)
  .handler(async ({ data: slug }) => {
    deletePost(slug);
    return { success: true };
  })

import { createFileRoute, notFound } from '@tanstack/react-router'
import { getPostBySlugFn } from '../serverFunctions'
import { marked } from 'marked'

export const Route = createFileRoute('/posts/$slug')({
  loader: async ({ params: { slug } }) => {
    const post = await getPostBySlugFn({ data: slug })
    if (!post || !post.published) {
      if (typeof window === 'undefined') {
        const { setResponseStatus } = await import('@tanstack/react-start/server')
        setResponseStatus(404)
      }
      throw notFound()
    }
    return post
  },
  notFoundComponent: () => {
    return (
      <main className="page-wrap px-4 py-12">
        <section className="island-shell rounded-2xl p-6 sm:p-8 text-center">
          <h1 className="text-4xl font-bold text-[var(--sea-ink)] mb-4">Not Found</h1>
          <p className="text-[var(--sea-ink-soft)]">The post you are looking for does not exist or is a draft.</p>
        </section>
      </main>
    )
  },
  component: PostDetail,
})

function PostComponent() {
  const post = Route.useLoaderData()
  const htmlBody = marked.parseSync(post.body) as string

  return (
    <main className="page-wrap px-4 py-12">
      <article className="island-shell rounded-2xl p-6 sm:p-8">
        <header className="mb-8 border-b border-[var(--line)] pb-6">
          <h1 className="text-4xl font-bold text-[var(--sea-ink)] mb-3">{post.title}</h1>
          <div className="flex flex-wrap gap-2 mb-4">
            {post.tags.map((tag) => (
              <a
                key={tag}
                href={`/?tag=${encodeURIComponent(tag)}`}
                className="rounded-full bg-[var(--chip-bg)] border border-[var(--chip-line)] px-3 py-1 text-xs font-semibold text-[var(--lagoon-deep)] transition hover:bg-[rgba(79,184,178,0.24)]"
              >
                #{tag}
              </a>
            ))}
          </div>
        </header>
        <div
          data-testid="post-body"
          className="prose max-w-none text-[var(--sea-ink-soft)] leading-relaxed space-y-4"
          dangerouslySetInnerHTML={{ __html: htmlBody }}
        />
      </article>
    </main>
  )
}

function PostDetail() {
  return <PostComponent />
}

import { createFileRoute } from '@tanstack/react-router'
import { getPostsFn } from '../serverFunctions'

export const Route = createFileRoute('/')({
  validateSearch: (search: Record<string, unknown>) => {
    return {
      tag: typeof search.tag === 'string' ? search.tag : undefined,
    }
  },
  loaderDeps: ({ search: { tag } }) => ({ tag }),
  loader: async ({ deps: { tag } }) => {
    return getPostsFn({ data: { tag, admin: false } })
  },
  component: App,
})

