import { createPost, getPosts, getPublishedPosts, getPostBySlug, updatePost, deletePost, isSlugUnique } from './src/db.js';

console.log('--- Testing Database Operations ---');

// 1. Clear database
import Database from 'better-sqlite3';
const db = new Database('blog.db');
db.exec('DELETE FROM posts');
console.log('Database cleared.');

// 2. Create posts
const post1 = createPost({
  title: 'My First Post',
  body: 'This is the body of my **first** post. It is written in Markdown.',
  tags: ['news', 'tech'],
  published: true,
});
console.log('Post 1 created:', post1);

const post2 = createPost({
  title: 'My First Post', // Same title to test slug collision
  body: 'This is a draft post body.',
  tags: ['tech'],
  published: false,
});
console.log('Post 2 created:', post2);

const post3 = createPost({
  title: 'Another Post',
  body: 'Another interesting story.',
  tags: ['life'],
  published: true,
});
console.log('Post 3 created:', post3);

// 3. Get posts
const allPosts = getPosts();
console.log('All posts count:', allPosts.length);
if (allPosts.length !== 3) throw new Error('Expected 3 posts');

const publishedPosts = getPublishedPosts();
console.log('Published posts count:', publishedPosts.length);
if (publishedPosts.length !== 2) throw new Error('Expected 2 published posts');

// 4. Get by slug
const retrieved1 = getPostBySlug('my-first-post');
console.log('Retrieved 1 by slug:', retrieved1?.title);
if (!retrieved1 || retrieved1.slug !== 'my-first-post') throw new Error('Failed to retrieve post 1');

const retrieved2 = getPostBySlug('my-first-post-2');
console.log('Retrieved 2 by slug:', retrieved2?.title);
if (!retrieved2 || retrieved2.slug !== 'my-first-post-2') throw new Error('Failed to retrieve post 2');

// 5. Update post
updatePost(retrieved2.id, {
  title: 'My Updated First Post',
  body: 'Updated body.',
  tags: ['tech', 'updates'],
  published: true,
});
const updated2 = getPostBySlug('my-updated-first-post');
console.log('Updated post 2:', updated2);
if (!updated2 || updated2.slug !== 'my-updated-first-post' || !updated2.published) throw new Error('Failed to update post 2');

// 6. Delete post
deletePost('my-updated-first-post');
const afterDelete = getPostBySlug('my-updated-first-post');
console.log('Post 2 after delete:', afterDelete);
if (afterDelete !== null) throw new Error('Expected post 2 to be deleted');

console.log('All database tests passed successfully!');

