import { createPost } from './src/db.ts';
import Database from 'better-sqlite3';

const db = new Database('blog.db');
db.exec('DELETE FROM posts');

createPost({
  title: 'Welcome to TanStack Start Blog',
  body: 'This is the very first post on our brand new blog! It is written in **Markdown**.\n\n## Features of this CMS\n* **SSR (Server-Side Rendering)**: Fast initial page loads and excellent SEO.\n* **Server Functions**: Easy communication between client and server.\n* **SQLite Database**: Lightweight and highly reliable local storage.\n\nHope you enjoy reading!',
  tags: ['welcome', 'tech', 'react'],
  published: true,
});

createPost({
  title: 'My Secret Draft Post',
  body: 'This is a draft post. It should **never** be visible to the public. Only admins can see it in the dashboard!',
  tags: ['secret', 'draft'],
  published: false,
});

createPost({
  title: 'A Guide to Markdown',
  body: 'Markdown is a lightweight markup language that you can use to add formatting elements to plaintext text documents.\n\n### Formatting Examples\n* **Bold text** using `**bold**`\n* *Italic text* using `*italic*`\n* [Links](https://tanstack.com) using `[text](url)`\n\nEnjoy writing in Markdown!',
  tags: ['tech', 'guide'],
  published: true,
});

console.log('Database populated with sample posts.');
